    street: int
    desired_time: int
    value: int
    begin_hour: int
    end_hour: int

def calculate_time(sites: List[Site]) -> int:
    total = 0
    for i in range(len(sites) - 1):
        cur = sites[i]
        next_site = sites[i + 1]
        travel_time = abs(cur.avenue - next_site.avenue) + abs(cur.street - next_site.street)
        total += cur.desired_time + travel_time
    return total

class MessageBody(BaseModel):
    sites_data: Dict[int, Site]

class Info(BaseModel):
    sender: str
    receiver: str
    difficulty: str
    message: List[BaseModel]

