            for i, site in enumerate(sites):
                if site == site1:
                    current_hour = int(time()) + site1.desired_time
                    if current_hour > site1.end_hour:
                        return False
                    current_hour += abs(site1.avenue - site.avenue) + abs(site1.street - site.street)
                if i < len(sites):
                    current_hour += site.desired_time
                    if current_hour > site.end_hour:
                        return False
                    current_hour += abs(site.avenue - sites[i].avenue) + abs(site.street - sites[i].street)
            if current_hour > site2.end_hour:
                return False
    return True

def calculate_value(sites: List[Site]) -> int:
    return sum(site.value for site in sites)

