    sites_list = list(sites_data.values())
    max_value = 0
    optimal_tour = []

    for perm in permutations(sites_list):
        if check_validity(perm):
            total_value = calculate_value(perm)
            if total_value > max_value:
                max_value = total_value
                optimal_tour = list(perm)

    return [i for i, site in enumerate(sites_list) if site in optimal_tour]

