# Step 1: Sort sites by their reward values in descending order
def sort_sites_by_value(sites: Dict[int, Dict[str, Union[int, dict]]]) -> List[int]:
    return sorted(sites.keys(), key=lambda x: sites[x]['value'], reverse=True)

# Step 2: Generate the optimal sequence using a DFS approach to explore feasible paths
def dfs(sites: Dict[int, Dict[str, Union[int, dict]]], index: int, current_time: int, path: List[int], visited: Set[int], result: List[List[int]]) -> List[List[int]]:
    if index == len(sites):
        result.append(path[:])
        return result

    for i in range(len(sites))::
        if i not in visited:
            site = sites[i]
            travel_time = manhattan_distance((0,0), (site['avenue'], site['street']))
            if current_time + travel_time + site['desiredtime'] <= site['endhour'] * 100:
                path.append(i)
                visited.add(i)
                dfs(sites, index + 1, current_time + travel_time + site['desiredtime'], path, visited, result)
                path.pop()
                visited.remove(i)
    return result

def manhattan_distance(a: tuple, b: tuple) -> int:
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def optimize_tour(sites: Dict[int, Dict[str, Union[int, dict]]]) -> List[int]:
    sorted_sites = sort_sites_by_value(sites)
    result = dfs(sites, 0, 0, [], set(), [])
    # Return the sequences with the maximum value
    max_value = max(sum(sites[s]["value"] for s in path) for path in result)
    for path in result:
        if sum(sites[s]["value"] for s in path) == max_value:
            return path

