    visited_sites = [] 
    current_time = 0 
    total_value = 0 

    current_site = min(sites_data.keys(), key=lambda k: sites_data[k]['beginhour'])

    while current_site in sites_data:
        site = sites_data[current_site]
        if (current_time + site['desired_time']) <= 24 * 60 and site['begin_hour'] <= current_time <= site['end_hour']:
            visited_sites.append(current_site)
            total_value += site['value']
            current_time += site['desired_time']
            # Sort remaining sites based on best value-to-time ratio feasible within the constraints of the last site's end time 
            feasible_sites = {k: v for k, v in sites_data.items() if (current_time <= v['end_hour'] and v['begin_hour'] <= current_time <= v['end_hour'])}
            if feasible_sites:
                next_site = max(feasible_sites, key=lambda k: feasible_sites[k]['value'] / feasible_sites[k]['desired_time']) 
            else:
                break 
            current_site = next_site
